    },
    {
      "claim": "Lisinopril's 25% absorption is a caveat that low Caco-2 permeability does not always mean F<20%, but the query has more extreme polarity/ionization and no active-transport evidence, so it does not overturn the low prediction.",
      "card_ids": ["C51"]
    }
  ],
  "new_evidence_assessment": [
